int ext4_orphan_del(handle_t *handle, struct inode *inode) {
    struct super_block *sb = inode->i_sb;
    struct ext4_super_block *es = EXT4_SB(sb);
    struct ext4_inode_info *ei = EXT4_I(inode);
    int err = 0;

    if (!EXT4_HAS_INCOMPAT_FEATURE(sb, EXT4_FEATURE_INCOMPAT_ORPHAN_FILE))
        return 0;

    mutex_lock(&EXT4_SB(sb)->s_orphan_lock);

    if (ei->i_orphan_list_entry.next || ei->i_orphan_list_entry.prev) {
        list_del(&ei->i_orphan_list_entry);
        ei->i_orphan_list_entry.next = NULL;
        ei->i_orphan_list_entry.prev = NULL;

        if (handle) {
            err = ext4_journal_get_write_access(handle, inode->i_ino);
            if (err)
                goto out_unlock;

            if (!EXT4_SB(sb)->s_orphan_list.next) {
                es->s_last_orphan = 0;
                err = ext4_handle_dirty_metadata(handle, sb, es);
            } else {
                struct inode *prev_inode = list_prev_entry(inode, i_orphan_list_entry);
                EXT4_I(prev_inode)->i_next_orphan = 0;
                err = ext4_mark_inode_dirty(handle, prev_inode);
            }

            if (!err)
                err = ext4_mark_inode_dirty(handle, inode);
        }

        if (!err)
            EXT4_I(inode)->i_flags &= ~EXT4_INODE_IN_ORPHAN_FILE;
    }

out_unlock:
    mutex_unlock(&EXT4_SB(sb)->s_orphan_lock);
    return err;
}

int ext4_orphan_del(handle_t *handle, struct inode *inode) {
    struct ext4_inode_info *ei = EXT4_I(inode);
    struct ext4_super_block *es = EXT4_SB(inode->i_sb)->s_es;
    struct inode *next_orphan;
    int err = 0;

    if (!EXT4_HAS_JOURNAL(inode->i_sb))
        return 0;

    mutex_lock(&EXT4_SB(inode->i_sb)->s_orphan_lock);

    if (ei->i_orphan) {
        next_orphan = ei->i_orphan;
        ei->i_orphan = NULL;

        if (next_orphan == inode) {
            EXT4_SB(inode->i_sb)->s_es->s_last_orphan = 0;
        } else {
            struct ext4_inode_info *prev_ei = EXT4_I(next_orphan);
            while (prev_ei->i_orphan != inode) {
                prev_ei = EXT4_I(prev_ei->i_orphan);
            }
            prev_ei->i_orphan = next_orphan;
            EXT4_I(inode)->i_orphan = NULL;
        }

        if (handle) {
            err = ext4_journal_get_write_access(handle, inode->i_ino);
            if (err)
                goto out_unlock;

            err = ext4_orphan_update(inode, handle, 0);
            if (err)
                goto out_unlock;
        }

        mark_inode_dirty(inode);
    }

out_unlock:
    mutex_unlock(&EXT4_SB(inode->i_sb)->s_orphan_lock);
    return err;
}

int ext4_orphan_del(handle_t *handle, struct inode *inode) {
    struct super_block *sb = inode->i_sb;
    struct ext4_sb_info *sbi = EXT4_SB(sb);
    struct ext4_inode_info *ei = EXT4_I(inode);
    int err = 0;

    if (!ext4_journal_t_need(sb)) {
        return 0;
    }

    journal_lock_orphan_list(sbi->s_journal);
    if (ei->i_orphan_list_entry.next == NULL) {
        goto unlock_out;
    }

    if (handle != NULL) {
        err = ext4_reserve_inode_write(handle, inode, NULL);
        if (err) {
            goto unlock_out;
        }
    }

    if (sbi->s_orphan == inode) {
        sbi->s_orphan = NULL;
        if (handle != NULL) {
            EXT4_SB(sb)->s_dirty = 1;
        }
    } else {
        struct inode *prev_inode = NULL;
        struct list_head *pos;

        list_for_each(pos, &sbi->s_orphan_list) {
            struct inode *tmp_inode = list_entry(pos, struct inode, i_list);
            if (tmp_inode == inode) {
                break;
            }
            prev_inode = tmp_inode;
        }

        if (prev_inode != NULL) {
            struct ext4_inode_info *prev_ei = EXT4_I(prev_inode);
            prev_ei->i_next_orphan = NULL;
            if (handle != NULL) {
                ext4_mark_inode_dirty(handle, prev_inode);
            }
        }
    }

    list_del_init(&ei->i_orphan_list_entry);
    ext4_mark_inode_dirty(handle, inode);

unlock_out:
    journal_unlock_orphan_list(sbi->s_journal);
    return err;
}

int ext4_orphan_del(handle_t *handle, struct inode *inode) {
    struct super_block *sb = inode->i_sb;
    struct ext4_sb_info *sbi = EXT4_SB(sb);
    struct ext4_inode_info *ei = EXT4_I(inode);
    struct ext4_inode *orphan;
    __u32 ino;
    int err = 0;

    if (!EXT4_HAS_INCOMPAT_FEATURE(sb, EXT4_FEATURE_INCOMPAT_ORPHAN_FILE))
        return 0;

    lock_orphan_list(sbi);

    if (!ei->i_orphan) {
        unlock_orphan_list(sbi);
        return -EINVAL;
    }

    ino = cpu_to_le32(inode->i_ino);

    if (ino == le32_to_cpu(sbi->s_es->s_last_orphan)) {
        sbi->s_es->s_last_orphan = ei->i_orphan;
        if (sbi->s_es->s_last_orphan == 0)
            err = ext4_handle_dirty_super(handle, sb);
    }

    if (handle) {
        err = ext4_journal_get_write_access(handle, inode->i_sb, ei->i_bh,
                                              EXT4_JOURNAL_ABORT_ON_ERR);
        if (err)
            goto out;
    }

    if (ino != le32_to_cpu(sbi->s_es->s_last_orphan)) {
        orphan = ext4_get_inode(inode->i_sb, ei->i_orphan);
        if (!orphan) {
            err = -EINVAL;
            goto out;
        }
        orphan->i_block[0] = ino;
        ext4_mark_inode_dirty(handle, &orphan->vfs_inode);
    }

    ei->i_orphan = 0;
    ext4_mark_inode_dirty(handle, inode);

out:
    unlock_orphan_list(sbi);
    return err;
}

int ext4_orphan_del(handle_t *handle, struct inode *inode) {
    struct super_block *sb = inode->i_sb;
    struct ext4_super_block *es = EXT4_SB(sb);
    struct ext4_inode_info *ei = EXT4_I(inode);
    struct ext4_iloc iloc;
    int err = 0;

    if (!EXT4_HAS_INCOMPAT_FEATURE(sb, EXT4_FEATURE_INCOMPAT_JOURNAL))
        return 0;

    down_read(&EXT4_SB(sb)->s_orphan_lock);

    if (!ei->i_orphan) {
        up_read(&EXT4_SB(sb)->s_orphan_lock);
        return 0;
    }

    if (handle) {
        err = ext4_journal_get_write_access(handle, inode->i_ino, sb);
        if (err) {
            up_read(&EXT4_SB(sb)->s_orphan_lock);
            return err;
        }
    }

    if (ei == EXT4_SB(sb)->s_orphan) {
        EXT4_SB(sb)->s_orphan = ei->i_orphan;
    } else {
        struct ext4_inode_info *prev;

        prev = EXT4_SB(sb)->s_orphan;
        while (prev && prev->i_orphan != ei)
            prev = prev->i_orphan;

        if (prev)
            prev->i_orphan = ei->i_orphan;
        else {
            up_read(&EXT4_SB(sb)->s_orphan_lock);
            return -EINVAL;
        }
    }

    ei->i_orphan = NULL;
    mark_inode_dirty(inode);
    up_read(&EXT4_SB(sb)->s_orphan_lock);

    return err;
}
